&lt;td&gt;216&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;&lt;strong&gt;Gain&lt;/strong&gt;&lt;/td&gt;
&lt;td&gt;&lt;strong&gt;40.7%&lt;/strong&gt;&lt;/td&gt;
